const raw = $input.first().json;
const b = raw.body ?? raw;
const events = ['problem_started', 'session_end', 'submission', 'reflection', 'coach_requested'];
const uuid = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
if (!events.includes(b.event)) throw new Error('Unsupported event: ' + b.event);
if (!uuid.test(String(b.profile_id || ''))) throw new Error('profile_id must be a UUID');
const p = b.problem || {};
const slug = String(p.slug || b.problem_slug || '');
const diff = String(p.difficulty || 'Unknown');
const arr = v => Array.isArray(v) ? v.map(String) : [];
const int = v => Math.max(0, Math.round(Number(v) || 0));
if (['problem_started', 'submission', 'coach_requested'].includes(b.event) && !slug) throw new Error('problem.slug is required');
let result = null;
if (b.event === 'submission') {
  result = String(b.result || '').trim().toLowerCase().replace(/[\s-]+/g, '_');
  const ok = ['accepted', 'wrong_answer', 'time_limit_exceeded', 'runtime_error', 'memory_limit_exceeded', 'compile_error', 'other'];
  if (!ok.includes(result)) throw new Error('Unsupported result: ' + b.result);
}
if (b.event === 'reflection' && !uuid.test(String(b.attempt_id || ''))) throw new Error('attempt_id (uuid) is required for reflection');
if (b.event === 'session_end' && !uuid.test(String(b.session_id || ''))) throw new Error('session_id (uuid) is required for session_end');
const conf = Number(b.confidence);
const ts = b.timestamp && !isNaN(Date.parse(b.timestamp)) ? new Date(b.timestamp).toISOString() : null;
return [{ json: {
  event: b.event,
  profile_id: b.profile_id,
  problem: {
    slug,
    title: String(p.title || slug),
    difficulty: diff.charAt(0).toUpperCase() + diff.slice(1).toLowerCase(),
    url: String(p.url || (slug ? 'https://leetcode.com/problems/' + slug + '/' : '')),
    patterns: arr(p.patterns),
    topics: arr(p.topics)
  },
  session_id: b.session_id || null,
  attempt_id: b.attempt_id || null,
  timestamp: ts,
  result,
  duration_seconds: int(b.duration_seconds),
  active_seconds: int(b.active_seconds || b.duration_seconds),
  hints_used: int(b.hints_used),
  solution_viewed: b.solution_viewed === true,
  editorial_viewed: b.editorial_viewed === true,
  confidence: conf >= 1 && conf <= 5 ? Math.round(conf) : null,
  error_types: arr(b.error_types),
  reflection: b.reflection && typeof b.reflection === 'object' ? b.reflection : {},
  request_type: b.request_type || 'hint',
  hint_level: Number(b.hint_level) || null,
  confirm_solution: b.confirm_solution === true
} }];

