parameters.jsCode:
const ev = $('Validate Event').first().json;
const ses = $('Create Session').first().json;
const rows = $input.all().map(i => i.json).filter(r => r.pattern);
const pats = rows.map(r => ({
  pattern: r.pattern,
  mastery_pct: Math.round(Number(r.mastery || 0) * 100),
  days_since: r.days_since,
  review_due: r.review_due === true,
  recognition_signals: r.recognition_signals
}));
const weak = pats.filter(p => p.mastery_pct < 60);
let message;
if (!pats.length) message = 'No pattern is mapped to this problem yet. Before coding, name the pattern and the constraint that decides the algorithm.';
else if (pats.some(p => p.review_due)) message = 'Review due: ' + pats.filter(p => p.review_due).map(p => p.pattern).join(', ') + '. Try it without hints.';
else if (weak.length) message = 'Focus on recognizing the pattern before coding: ' + weak.map(p => p.pattern).join(', ');
else message = 'Try independently first. Do not open hints unless you are genuinely stuck.';
return [{ json: {
  success: true,
  event: 'problem_started',
  session_id: ses.id,
  problem: ev.problem,
  mode: weak.length ? 'guided_practice' : 'independent_practice',
  coach: { likely_pattern: pats[0] ? pats[0].pattern : null, patterns: pats, message }
} }];

const first = $input.first().json || {};
// An upstream database failure arrives here as an error item.
if (first.error || (!first.profile_id && !first.patterns)) {
  let src = 'recalc';
  try {
    const ev = $('Validate Event').first().json;
    if (ev && ev.event) src = ev.event === 'reflection' ? 'reflection' : 'submission';
  } catch (e) {}
  return [{ json: { skip: true, degraded: true, source: src, profile_id: first.profile_id || null } }];
}

const d = first;
const att = d.attempt || {};
const src = att._source || 'recalc';
const pats = d.patterns || [];
if (!d.profile_id || pats.length === 0) return [{ json: { skip: true, source: src, profile_id: d.profile_id || null } }];

const DAY = 86400000;
const nowMs = Date.now();
const LADDER = [1, 3, 7, 14, 30, 60];
const DIFF_W = { Easy: 0.7, Medium: 1, Hard: 1.3 };
// A failure still carries information, but how much depends on how it failed.
// A TLE means the shape was recognised and the complexity was not; a compile
// error says almost nothing about whether the pattern is understood.
const FAIL_SCORE = { time_limit_exceeded: 0.3, memory_limit_exceeded: 0.28, wrong_answer: 0.2, runtime_error: 0.15, compile_error: 0.1, other: 0.15 };
const imported = h => h.source === 'leetcode_sync' || h.source === 'import';
const ts = h => { const t = h.submitted_at ? Date.parse(h.submitted_at) : NaN; return isNaN(t) ? 0 : t; };

const score = h => {
  if (h.result !== 'accepted') return FAIL_SCORE[h.result] != null ? FAIL_SCORE[h.result] : 0.15;
  let s = 1 - Math.min(Number(h.hints_used) || 0, 4) * 0.12;
  if (h.solution_viewed || h.editorial_viewed) s = Math.min(s, 0.3);
  if (imported(h)) s = Math.min(s, 0.65);
  if (h.confidence) s *= 0.75 + 0.25 * (Number(h.confidence) / 5);
  return Math.max(0, s);
};

return pats.map(p => {
  const hs = (d.history || [])
    .filter(h => (h.patterns || []).includes(p.name))
    .sort((a, b) => ts(a) - ts(b));
  const sk = (d.skills || []).find(s => s.name === p.name) || {};
  const prior = sk.prior_mastery == null ? 0 : Number(sk.prior_mastery);

  let num = 0, den = 0;
  hs.forEach((h, i) => {
    const t = ts(h);
    const ageDays = t ? Math.max(0, (nowMs - t) / DAY) : 0;
    // Two decays, because position in the sequence and elapsed time are not the
    // same thing: practice from six months ago should not weigh like yesterday's.
    let w = (DIFF_W[h.difficulty] || 1) * Math.pow(0.95, hs.length - 1 - i) * Math.exp(-ageDays / 120);
    if (h.result !== 'accepted') w *= 0.6;
    if (imported(h)) w *= 0.6;
    num += w * score(h);
    den += w;
  });

  // The self-rating anchors the estimate on day one and fades as real attempts
  // accumulate, so demonstrated evidence overtakes what was claimed.
  const PRIOR_W = hs.length === 0 ? 2 : Math.max(0.4, 1.5 * Math.exp(-hs.length / 6));
  const mastery = Math.max(0, Math.min(1, (num + PRIOR_W * prior) / (den + PRIOR_W)));

  const solved = new Map();
  hs.filter(h => h.result === 'accepted').forEach(h => solved.set(h.problem_slug, h.difficulty));
  const cnt = k => [...solved.values()].filter(x => x === k).length;
  const timed = hs.filter(h => h.result === 'accepted' && Number(h.duration_seconds) > 0);
  const errs = {};
  hs.forEach(h => (Array.isArray(h.error_types) ? h.error_types : []).forEach(e => { errs[e] = (errs[e] || 0) + 1; }));
  const confs = hs.filter(h => h.confidence).slice(-5).map(h => Number(h.confidence));

  // spaced repetition: 1,3,7,14,30,60 days; strong = climb, assisted = hold, failed = drop two rungs
  const live = src === 'submission';
  let idx = sk.review_interval_days ? LADDER.findIndex(x => x >= Number(sk.review_interval_days)) : -1;
  if (live) {
    if (att.performance === 'strong') idx = Math.min(idx + 1, LADDER.length - 1);
    else if (att.performance === 'assisted') idx = Math.max(idx, 0);
    else idx = Math.max(idx - 2, 0);
  }
  const interval = LADDER[Math.max(idx, 0)];

  return { json: {
    skip: false, source: src, profile_id: d.profile_id, pattern: p.name,
    mastery: Number(mastery.toFixed(4)),
    confidence: confs.length ? Number((confs.reduce((a, b) => a + b, 0) / confs.length).toFixed(2)) : null,
    problems_solved: solved.size, easy_solved: cnt('Easy'), medium_solved: cnt('Medium'), hard_solved: cnt('Hard'),
    problems_attempted: hs.length,
    avg_time_seconds: timed.length ? Math.round(timed.reduce((a, h) => a + Number(h.duration_seconds), 0) / timed.length) : 0,
    hint_rate: hs.length ? Number((hs.filter(h => Number(h.hints_used) > 0).length / hs.length).toFixed(3)) : 0,
    failure_rate: hs.length ? Number((hs.filter(h => h.result !== 'accepted').length / hs.length).toFixed(3)) : 0,
    last_practiced: hs.length ? hs[hs.length - 1].submitted_at : null,
    review_interval_days: interval,
    update_review: live,
    error_profile: JSON.stringify(errs),
    result: att.result || 'recalc'
  } };
});

const rows = $input.all().map(i => i.json);
const scored = rows.filter(r => r && r.pattern && r.mastery !== null && r.mastery !== undefined);
const degraded = rows.some(r => r && r.degraded) && scored.length === 0;

if (degraded) {
  // The attempt itself may well have been recorded before the failure, so pass
  // back its id — the extension needs it to attach a reflection.
  let attemptId = null;
  try { attemptId = $('Record Attempt').first().json.id || null; } catch (e) { /* not a submission */ }
  if (!attemptId) { try { attemptId = $('Save Reflection').first().json.id || null; } catch (e) {} }
  return [{ json: {
    success: false,
    error: 'skill_update_unavailable',
    event: 'submission',
    attempt_id: attemptId,
    skills_updated: [],
    coach: { message: 'Attempt recorded. The skill update could not run just now and will be re-derived on the next sync.',
      next_action: 'continue' }
  } }];
}

const ctx = $('Load Skill Inputs').first().json;
const a = (ctx && ctx.attempt) || {};
const skills = scored.map(r => ({ pattern: r.pattern, mastery_pct: Math.round(Number(r.mastery) * 100), problems_solved: r.problems_solved, review_interval_days: r.review_interval_days, next_review: r.next_review }));
const isReflection = a._source === 'reflection';
let message, next;
if (isReflection) { message = 'Reflection saved. Your skill profile was re-scored with it.'; next = 'continue'; }
else if (a.result === 'accepted' && a.performance === 'strong') { message = 'Independent solve. Real evidence that the pattern is sticking.'; next = 'review_later'; }
else if (a.result === 'accepted') { message = 'Accepted, but assisted. It will come back for an unaided review.'; next = 'spaced_review'; }
else { message = 'Useful evidence. Name the exact failure before you retry.'; next = 'diagnose_and_retry'; }
return [{ json: {
  success: true,
  event: isReflection ? 'reflection' : 'submission',
  attempt_id: a.id || null,
  attempt_number: a.attempt_number || null,
  result: a.result || null,
  performance: a.performance || null,
  skills_updated: skills,
  coach: { message, next_action: next,
    ask_reflection: !isReflection && a.result === 'accepted',
    ask_error_types: !isReflection && a.performance !== 'strong' }
} }];

const ev = $('Validate Event').first().json;
const ctx = $input.first().json;
const pats = (ctx.patterns || []).slice().sort((a, b) => Number(a.mastery) - Number(b.mastery));
const main = pats[0] || null;
let level = ev.hint_level
  || (ev.request_type === 'hint' && ev.hints_used > 0 ? ev.hints_used + 1 : null)
  || ({ initial_guidance: 1, hint: 2, approach: 3, solution: 5 }[ev.request_type] || 1);
level = Math.max(1, Math.min(5, level));
if (level === 5 && !ev.confirm_solution) level = 4;
const name = main ? main.pattern : null;
const sig = main && main.recognition_signals ? main.recognition_signals : 'the input structure and the constraint that rules out the naive approach';
let hint = '';
if (level === 1) hint = 'Recognition: reread the statement and look for ' + sig + '. What does that suggest?';
else if (level === 2) hint = name ? 'Direction: this fits ' + name + '. What state must you maintain as you process the input, and when does it become invalid?' : 'Direction: define the smallest state you must remember while scanning the input.';
else if (level === 3) hint = main && main.template ? 'Approach: ' + main.template : 'Approach: write the brute force first, then find the repeated work to remove.';
if (level <= 3 && main && main.common_mistakes) hint += ' Watch out for: ' + main.common_mistakes + '.';
return [{ json: { level, pattern: name, hint, needs_ai: level >= 4, next_level: Math.min(5, level + 1), problem: ev.problem } }];

const base = $('Build Hint').first().json;
const cur = $input.first().json;
const ai = cur.output && cur.output[0] && cur.output[0].content && cur.output[0].content[0] && cur.output[0].content[0].text;
let hint = base.hint, source = 'template';
if (base.needs_ai) {
  if (ai) { hint = ai; source = 'ai'; }
  else hint = 'The AI step is unavailable right now. Use hint level 3, or retry in a moment.';
}
return [{ json: { success: true, event: 'coach_requested', hint_level: base.level,
  coach: { pattern: base.pattern, hint, source, next_level: base.next_level, reveal_solution: base.level === 5 } } }];

const d = $input.first().json;
const pf = d.profile;
if (!pf) throw new Error('No profile found. POST /webhook/dsa-coach/cold-start first (or insert a row into profiles).');
const DAY = 86400000, now = new Date();
const pats = d.patterns || [], cands = d.candidates || [], recent = d.recent || [];
const budget = Number(pf.daily_minutes) || (Number(pf.hours_per_week) ? Math.round(Number(pf.hours_per_week) * 60 / 7) : 45);
const gapDays = d.last_attempt_at ? Math.floor((now - new Date(d.last_attempt_at)) / DAY) : null;
let toTarget = pf.target_date ? Math.ceil((new Date(pf.target_date) - now) / DAY) : null;
// A date that has already gone by must not pin the coach in taper mode forever.
const targetPassed = toTarget !== null && toTarget < 0;
if (targetPassed) toTarget = null;

// Nothing seeded to plan against — say so rather than failing on an empty list.
if (!pats.length) {
  return [{ json: { profile_id: pf.id, email: pf.email, via: pf.via, plan: {
    plan_date: d.today, mode: 'build', restart_step: 0, days_to_target: toTarget, budget_minutes: budget,
    total_minutes: 0, difficulty_trend: 0, items: [], priorities: [], skills: [],
    message: 'No patterns are seeded yet. Load the patterns table (and at least one target set) before the coach can plan a day.'
  } } }];
}

// ---- 1. coach mode -------------------------------------------------------
let mode = 'build', restartStep = 0;
if (toTarget !== null) mode = toTarget <= 3 ? 'taper' : toTarget <= 14 ? 'mock' : toTarget <= 28 ? 'consolidate' : 'build';
const prev = (d.recent_plans || []).find(p => Number(p.restart_step) > 0);
const prevAge = prev ? (new Date(d.today) - new Date(prev.plan_date)) / DAY : 99;
if (mode !== 'taper') {
  if (gapDays !== null && gapDays >= 5) { mode = 'restart'; restartStep = 1; }
  else if (prev && Number(prev.restart_step) === 1 && prevAge <= 2 && gapDays !== null && gapDays <= 1) { mode = 'restart'; restartStep = 2; }
}

// ---- 2. difficulty controller (recent evidence, not totals) ---------------
const NAMES = ['Easy', 'Medium', 'Hard'], IDX = { Easy: 0, Medium: 1, Hard: 2 };
let trend = 0;
const l4 = recent.slice(0, 4), l2 = recent.slice(0, 2);
if (l4.length === 4 && l4.filter(r => r.performance === 'strong').length >= 3) trend = 1;
if (l2.length === 2 && l2.every(r => r.result !== 'accepted')) trend = -1;
// Overall form is a blunt instrument: a strong run on arrays says nothing about
// graphs. Let each pattern's own recent attempts adjust its difficulty too.
const patTrend = name => {
  const rs = recent.filter(r => (r.patterns || []).includes(name)).slice(0, 3);
  if (rs.length >= 2 && rs.every(r => r.result !== 'accepted')) return -1;
  if (rs.length >= 2 && rs.filter(r => r.performance === 'strong').length >= 2) return 1;
  return 0;
};
const want = p => {
  const base = p.m < 0.35 ? 0 : p.m < 0.7 ? 1 : 2;
  const adj = Math.max(-1, Math.min(1, trend + patTrend(p.name)));
  return NAMES[Math.max(0, Math.min(2, base + adj))];
};

// ---- 3. priority = weight x gap x forgetting ------------------------------
const byName = Object.fromEntries(pats.map(p => [p.name, p]));
const target = t => ({ A: 0.8, B: 0.65, C: 0.5 }[t] || 0.6);
const scored = pats.map(p => {
  const w = Number(p.weight) || 0.5, m = Number(p.mastery) || 0;
  const gap = Math.max(0.05, target(p.tier) - m);
  let f = 1;
  if (p.days_since !== null && p.days_since !== undefined) f += Math.min(1.5, p.days_since / 14);
  if (p.review_due) f += 0.5;
  const uncal = Number(p.attempted) === 0 && m > 0;
  if (uncal) f += 0.3;
  const blocked = (p.prerequisites || []).some(q => byName[q] && Number(byName[q].mastery) < 0.35);
  let priority = w * gap * f;
  if (blocked && mode === 'build') priority *= 0.4;
  if (mode === 'build' && Number(p.attempted) === 0) priority *= 1.15;
  if (mode === 'consolidate' && Number(p.attempted) > 0) priority *= 1.2;
  if (mode === 'taper' && m < 0.5) priority *= 0.3;
  // A pattern that just failed twice needs attention now, whatever the tier says.
  if (patTrend(p.name) === -1) priority *= 1.3;
  return { ...p, w, m, gap, f, uncal, blocked, priority };
}).sort((a, b) => b.priority - a.priority);

// ---- 4. problem picking from curated target sets -------------------------
const used = new Set();
const kind = c => Number(c.accepted_count) > 0 ? (Number(c.strong_count) > 0 ? 'mastered' : 'assisted') : (Number(c.tries) > 0 ? 'failed' : 'new');
const ageDays = c => c.last_attempt_at ? (now - new Date(c.last_attempt_at)) / DAY : 0;
const pick = (name, diff, kinds, cap) => {
  const fit = c => 1 - 0.5 * Math.abs((IDX[c.difficulty] ?? 1) - IDX[diff]) + (kind(c) === 'failed' ? 0.3 : 0)
    + (kind(c) === 'assisted' ? Math.min(ageDays(c), 30) * 0.01 : 0) - Number(c.position) * 0.001;
  let pool = cands.filter(x => (x.patterns || []).includes(name) && !used.has(x.slug) && kinds.includes(kind(x)));
  // When a difficulty is asked for explicitly it is a ceiling, not a preference:
  // a comeback day that hands back a Hard problem is not a comeback day.
  if (cap) pool = pool.filter(x => (IDX[x.difficulty] ?? 1) <= IDX[diff]);
  const c = pool.sort((a, b) => fit(b) - fit(a))[0];
  if (c) used.add(c.slug);
  return c || null;
};
const prob = c => c ? { slug: c.slug, title: c.title, difficulty: c.difficulty, url: c.url } : null;
const mins = dif => dif === 'Easy' ? 15 : dif === 'Medium' ? 25 : 35;
const why = p => 'weight ' + p.w.toFixed(2) + ' x gap ' + p.gap.toFixed(2) + ' x forgetting ' + p.f.toFixed(2)
  + (p.review_due ? ', review due' : '') + (p.uncal ? ', self-rating not verified yet' : '')
  + (patTrend(p.name) === -1 ? ', recent attempts failed' : '')
  + (p.blocked && mode === 'build' ? ', prerequisite still weak' : '');
const newItem = (p, type, w) => {
  const dif = w || want(p);
  const cap = !!w;
  const c = pick(p.name, dif, ['failed', 'new'], cap) || pick(p.name, dif, ['assisted'], cap);
  const d2 = c ? c.difficulty : dif;
  return { type: p.uncal && type === 'new' ? 'calibration' : type, pattern: p.name, minutes: mins(d2), difficulty: d2, problem: prob(c),
    note: c ? null : 'No curated ' + d2 + ' problem for ' + p.name + '. Pick any ' + d2 + ' problem tagged with it.', reason: why(p) };
};
const reviewItem = (p, w) => {
  const dif = w || (p.m < 0.5 ? 'Easy' : 'Medium');
  const c = pick(p.name, dif, ['assisted', 'failed'], true) || pick(p.name, dif, ['new'], true);
  return { type: 'review', pattern: p.name, minutes: 15, difficulty: c ? c.difficulty : dif, problem: prob(c),
    note: c ? null : 'No curated problem left for ' + p.name + '. Redo any problem you solved with help.', reason: why(p) };
};

// ---- 5. assemble the plan --------------------------------------------------
let items = [], message = '';
const practiced = scored.filter(p => Number(p.attempted) > 0);
const mockDay = mode !== 'restart' && mode !== 'taper' && d.dow === Number(pf.mock_weekday ?? 6);
if (mode === 'restart' && restartStep === 1) {
  const strong = practiced.slice().sort((a, b) => b.m - a.m)[0] || scored[0];
  items = [{ ...newItem(strong, 'restart_easy', 'Easy') }];
  message = "Welcome back. Let's rebuild momentum. One easy win today, nothing more.";
} else if (mode === 'restart') {
  const decayed = practiced.slice().sort((a, b) => (b.days_since || 0) - (a.days_since || 0)).slice(0, 2);
  while (decayed.length < 2 && scored[decayed.length]) decayed.push(scored[decayed.length]);
  items = decayed.map(p => ({ ...reviewItem(p), type: 'decay_review' }));
  message = 'Good to see you back. Two problems from the patterns that faded the most, then we return to the normal load.';
} else if (mode === 'taper') {
  const light = practiced.filter(p => p.m >= 0.4).sort((a, b) => b.f - a.f).slice(0, 3);
  const base = light.length ? light : (practiced.length ? practiced.slice(0, 2) : scored.slice(0, 2));
  items = base.map(p => reviewItem(p, 'Easy'));
  message = 'Taper: light review only, no new topics. Sleep matters more than one more problem.';
} else if (mockDay) {
  const a = scored[0], b2 = scored[1] || scored[0];
  const hardOk = b2.m >= 0.6 && trend >= 0;
  items = [{ ...newItem(a, 'mock', 'Medium'), minutes: 22, timed: true }, { ...newItem(b2, 'mock', hardOk ? 'Hard' : 'Medium'), minutes: 23, timed: true }];
  message = 'Weekly mock: 45 minutes, two problems, no hints. After each one, say the pattern and complexity out loud.';
} else {
  const pool = mode === 'consolidate' && practiced.length ? practiced : scored;
  const P1 = pool[0], P2 = pool.find(p => p !== P1);
  const R = scored.filter(p => Number(p.attempted) > 0 && (p.review_due || (p.days_since || 0) >= 7) && p !== P1 && p !== P2)
    .sort((a, b) => b.f * b.w - a.f * a.w)[0];
  const comps = [newItem(P1, 'new')];
  if (R) comps.push(reviewItem(R));
  if (P1.m < 0.6) comps.push({ type: 'recognition', pattern: P1.name, minutes: 5, detail: P1.recognition_signals, reason: 'Recognition is the real skill for ' + P1.name });
  comps.push({ type: 'explain', pattern: P1.name, minutes: 10, detail: "For today's main problem, state the pattern, why it fits, time and space complexity.", reason: 'Interview communication' });
  if (P2) comps.push(newItem(P2, 'new'));
  let used2 = 0;
  const chosen = [];
  comps.forEach((c, i) => { if (i === 0 || used2 + c.minutes <= budget) { chosen.push(c); used2 += c.minutes; } });
  const order = { recognition: 0, new: 1, calibration: 1, review: 2, explain: 3 };
  chosen.sort((a, b) => (order[a.type] ?? 1) - (order[b.type] ?? 1));
  items = chosen.map(c => mode === 'mock' && c.problem ? { ...c, timed: true } : c);
  message = mode[0].toUpperCase() + mode.slice(1) + ' mode' + (toTarget !== null ? ' - ' + toTarget + ' days to target' : '') + '. Top focus: ' + P1.name + '.'
    + (trend === -1 ? ' Recent attempts were rough, so difficulty is lowered and this pattern is reviewed first.' : trend === 1 ? ' You are on a strong run, so difficulty steps up.' : '');
}
if (targetPassed) message += ' Your target date has passed — set a new one to get deadline-aware planning back.';

const plan = {
  plan_date: d.today, mode, restart_step: restartStep, days_to_target: toTarget, budget_minutes: budget,
  total_minutes: items.reduce((s, x) => s + x.minutes, 0), message, difficulty_trend: trend,
  items: items.map((x, i) => ({ order: i + 1, ...x })),
  priorities: scored.slice(0, 6).map(p => ({ pattern: p.name, tier: p.tier, mastery: Number(p.m.toFixed(2)), priority: Number(p.priority.toFixed(3)), days_since: p.days_since, review_due: p.review_due })),
  skills: scored.map(p => ({ pattern: p.name, topic: p.topic, mastery: Math.round(p.m * 100), problems_solved: p.solved, last_practiced: p.last_practiced }))
};
return [{ json: { profile_id: pf.id, email: pf.email, via: pf.via, plan } }];

const { plan, email } = $('Priority Engine').first().json;
const label = { new: 'New', calibration: 'Calibrate', review: 'Review', recognition: 'Recognize', explain: 'Explain', mock: 'Mock', restart_easy: 'Easy win', decay_review: 'Refresh' };
const colour = { new: '#16a34a', calibration: '#0891b2', review: '#2563eb', recognition: '#7c3aed', explain: '#ca8a04', mock: '#dc2626', restart_easy: '#16a34a', decay_review: '#2563eb' };
const rows = plan.items.map(i => {
  const what = i.problem
    ? '<a href="' + i.problem.url + '" style="color:#111;font-weight:600;text-decoration:none;">' + i.problem.title + '</a> <span style="color:#888;">(' + i.problem.difficulty + ')</span>'
    : '<b>' + i.pattern + '</b>' + (i.note ? '<br><span style="color:#b45309;font-size:12px;">' + i.note + '</span>' : '');
  const extra = i.detail ? '<br><span style="color:#555;font-size:13px;">' + i.detail + '</span>' : '';
  return '<tr><td style="padding:10px 8px;border-bottom:1px solid #eee;">' + i.order + '</td>'
    + '<td style="padding:10px 8px;border-bottom:1px solid #eee;"><span style="background:' + (colour[i.type] || '#555') + ';color:#fff;border-radius:4px;padding:2px 8px;font-size:12px;">' + (label[i.type] || i.type) + '</span></td>'
    + '<td style="padding:10px 8px;border-bottom:1px solid #eee;">' + what + '<br><span style="color:#888;font-size:12px;">' + i.pattern + '</span>' + extra + '</td>'
    + '<td style="padding:10px 8px;border-bottom:1px solid #eee;">' + i.minutes + ' min' + (i.timed ? ' (timed)' : '') + '</td>'
    + '<td style="padding:10px 8px;border-bottom:1px solid #eee;color:#666;font-size:12px;">' + (i.reason || '') + '</td></tr>';
}).join('');
const html = '<div style="font-family:Arial,Helvetica,sans-serif;max-width:680px;margin:0 auto;">'
  + '<h2 style="margin-bottom:2px;">Today: ' + plan.plan_date + ' &middot; ' + plan.total_minutes + ' min</h2>'
  + '<p style="color:#444;margin-top:4px;">' + plan.message + '</p>'
  + '<table style="border-collapse:collapse;width:100%;font-size:14px;"><tr style="text-align:left;color:#888;font-size:12px;"><th>#</th><th>Type</th><th>Task</th><th>Time</th><th>Why</th></tr>' + rows + '</table>'
  + '<p style="color:#999;font-size:12px;margin-top:16px;">After each solve, submit the reflection in the side panel. That is what tunes tomorrow.</p></div>';
return [{ json: { email, subject: 'DSA Coach - ' + plan.mode + ' - ' + plan.total_minutes + ' min', html } }];

parameters.query:
SELECT id AS profile_id, leetcode_username, COALESCE(last_synced_at, 'epoch'::timestamptz) AS since
FROM profiles
WHERE leetcode_username IS NOT NULL AND leetcode_username <> '';

parameters.jsCode:
const profiles = $('Get Sync Profiles').all();
const out = [];
$input.all().forEach((item, i) => {
  const pf = profiles[i] && profiles[i].json;
  if (!pf) return;
  const since = new Date(pf.since).getTime() / 1000;
  const subs = (item.json && item.json.data && item.json.data.recentAcSubmissionList) || [];
  const seen = new Set();
  for (const s of subs) {
    const ts = Number(s.timestamp);
    if (ts > since && !seen.has(s.titleSlug)) {
      seen.add(s.titleSlug);
      out.push({ json: { profile_id: pf.profile_id, titleSlug: s.titleSlug, title: s.title, timestamp: String(s.timestamp) } });
    }
  }
});
return out;

return $input.all().map((item, i) => {
  const q = (item.json.data && item.json.data.question) || {};
  const src = $('Filter Recent Solves').all()[i].json;
  return { json: {
    profile_id: src.profile_id,
    slug: src.titleSlug,
    title: src.title,
    difficulty: q.difficulty || 'Unknown',
    topics: (q.topicTags || []).map(t => t.name),
    solved_at: new Date(Number(src.timestamp) * 1000).toISOString()
  } };
});

const raw = $input.first().json;
const b = raw.body ?? raw;
const uuid = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
const ratings = {};
for (const [k, v] of Object.entries(b.self_ratings || {})) { const n = Number(v); if (n >= 1 && n <= 5) ratings[k] = n; }
return [{ json: {
  profile_id: uuid.test(String(b.profile_id || '')) ? b.profile_id : '',
  name: String(b.name || 'Me'), email: String(b.email || ''),
  leetcode_username: String(b.leetcode_username || ''),
  target_company: String(b.target_company || ''), target_role: String(b.target_role || 'SWE'),
  target_date: /^\d{4}-\d{2}-\d{2}$/.test(String(b.target_date || '')) ? b.target_date : '',
  hours_per_week: Number(b.hours_per_week) || 7, daily_minutes: Number(b.daily_minutes) || 0,
  level: String(b.level || 'Intermediate'),
  target_sets: Array.isArray(b.target_sets) && b.target_sets.length ? b.target_sets.map(String) : ['starter'],
  self_ratings: ratings
} }];

const d = $input.first().json;
if (!d.profile) throw new Error('No profile found');
const pats = d.patterns || [];
const groups = {};
pats.forEach(p => { (groups[p.topic] = groups[p.topic] || []).push(p); });
const avg = ps => ps.reduce((s, p) => s + Number(p.mastery), 0) / ps.length;
const topics = Object.entries(groups).map(([t, ps]) => ({ t, avg: avg(ps), attempted: ps.some(p => Number(p.attempted) > 0), w: Math.max(...ps.map(p => Number(p.weight))) }));
const practiced = topics.filter(x => x.attempted).sort((a, b) => b.avg - a.avg);
const core = topics.filter(x => x.w >= 0.6).sort((a, b) => a.avg - b.avg);
const attention = pats.filter(p => Number(p.weight) >= 0.6 && Number(p.mastery) < 0.4)
  .sort((a, b) => Number(b.weight) * (0.8 - Number(b.mastery)) - Number(a.weight) * (0.8 - Number(a.mastery))).slice(0, 5);
const focus = core.slice(0, 3).map(x => x.t);
const li = s => '<li>' + s + '</li>';
const html = '<div style="font-family:Arial,Helvetica,sans-serif;max-width:640px;margin:0 auto;"><h2>Weekly DSA report</h2><ul>'
  + li('Problems: <b>' + d.problems + '</b>')
  + li('Independent: <b>' + d.independent + '</b> &middot; Hint-dependent: <b>' + d.hint_dependent + '</b> &middot; Solution-dependent: <b>' + d.solution_dependent + '</b>')
  + li('Strongest topic: <b>' + (practiced[0] ? practiced[0].t : 'n/a yet') + '</b>')
  + li('Weakest core topic: <b>' + (core[0] ? core[0].t : 'n/a') + '</b>')
  + li('Most common error: <b>' + (d.top_error || 'none logged') + '</b>')
  + li('Patterns reviewed: <b>' + d.patterns_reviewed + '</b>')
  + li('Patterns needing attention: <b>' + (attention.length ? attention.map(p => p.name).join(', ') : 'none') + '</b>')
  + li('Next week: <b>' + (focus.join(' + ') || 'keep going') + '</b>')
  + '</ul></div>';
return [{ json: { email: d.profile.email, subject: 'DSA Coach - weekly report', html } }];

const err = ($input.first().json && $input.first().json.error) || {};
const parts = [err.message, err.description, err.detail, err.hint].filter(v => v && String(v).trim());
const detail = parts.length ? parts.join(' | ') : (typeof err === 'string' ? err : JSON.stringify(err)) || 'unknown';
return [{ json: { success: false, error: 'backend_temporarily_unavailable', detail } }];

const err = ($input.first().json && $input.first().json.error) || {};
const parts = [err.message, err.description, err.detail, err.hint].filter(v => v && String(v).trim());
const detail = parts.length ? parts.join(' | ') : (typeof err === 'string' ? err : JSON.stringify(err)) || 'unknown';
return [{ json: {
  success: false,
  error: 'cold_start_failed',
  detail,
  hint: 'Open the failed execution in n8n and read the Save Profile And Priors node. Usual causes: the tables are not created yet, or profiles has a unique constraint (e.g. email) that this insert does not handle.'
} }];

const err = ($input.first().json && $input.first().json.error) || {};
const detail = String(err.message || err.description || err || 'invalid request');
// The most common cause by far: events sent before onboarding, while the
// extension still holds the placeholder profile_id instead of a real UUID.
const needsOnboarding = detail.indexOf('profile_id') !== -1;
return [{ json: {
  success: false,
  error: needsOnboarding ? 'profile_not_onboarded' : 'invalid_event',
  detail,
  hint: needsOnboarding
    ? 'Run onboarding first: POST /webhook/dsa-coach/cold-start to get a profile_id (UUID), then save it in the extension.'
    : 'Check the event name and required fields for this event type.'
} }];

// A database step in the shared skill engine failed. Whether anyone is waiting
// on a response depends on how we got here: live extension events pass through
// Validate Event, the nightly recalc does not.
let source = 'recalc';
try {
  const ev = $('Validate Event').first().json;
  if (ev && ev.event) source = ev.event === 'reflection' ? 'reflection' : 'submission';
} catch (e) { /* cron recalc: no webhook is waiting */ }
const err = ($input.first().json && $input.first().json.error) || {};
const parts = [err.message, err.description, err.detail].filter(v => v && String(v).trim());
const detail = parts.length ? parts.join(' | ') : 'database unavailable';
return [{ json: {
  skip: true,
  degraded: true,
  source,
  pattern: null,
  detail
} }];

// Reached only when a plan query failed. The cron run has nobody to answer, so
// work out which trigger started this execution before responding.
let via = 'schedule';
try { if ($('Plan Webhook').first().json) via = 'webhook'; } catch (e) { /* schedule run */ }
let plan = null;
try { plan = $('Priority Engine').first().json.plan || null; } catch (e) { /* failed before planning */ }
const err = ($input.first().json && $input.first().json.error) || {};
const parts = [err.message, err.description, err.detail, err.hint].filter(v => v && String(v).trim());
const detail = parts.length ? parts.join(' | ') : (typeof err === 'string' ? err : JSON.stringify(err)) || 'database unavailable';
// If only the save failed, the plan itself is still good — hand it over rather
// than making the user stare at an error for work already done.
if (plan) return [{ json: { via, success: true, warning: 'plan_not_persisted', detail, plan } }];
return [{ json: { via, success: false, error: 'backend_temporarily_unavailable', detail } }];
